pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // 1. Restrict to admissible domain: non-zero receiver, positive amount
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        // 2. Deploy a helper that always reverts on receive to model adversarial callee
        Reverter reverter = new Reverter();
        // The owner sends to the reverter; we test the case where transfer to receiver fails
        // Owner is the test contract itself, which deployed c, so owner = address(this)
        // Fund the contract so it can send
        vm.deal(address(c), amount);
        // 3. Execute sendTo as owner to the reverter; reference succeeds (though transfer reverts),
        //    bug reverts from require(receiver == address(0))
        c.sendTo(address(reverter), amount);
        // The reference calls transfer which fails, but the call does not revert (low-level)
        // If the call did not revert, we check the rule below
        // Rule: after a call from owner with non-zero receiver and positive amount,
        // the contract's balance decreases by amount if the low-level transfer did not revert
        // However, since the transfer always reverts here, balance should remain unchanged.
        // The bug reverts the whole transaction, so assertBalanceChange only runs for reference.
        uint256 balanceAfter = address(c).balance;
        // Reference: transfer reverts, so balance stays the same.
        // Bug: would never reach here (reverts on require). If reached, balanceAfter == 0.
        // But to keep the assertion general, we just assert that the call did not revert.
        // Actually, the reference does not revert because transfer failure does not bubble up.
        // So assertTrue(true) is not allowed; we need a general fact.
        // Fact: The contract's balance after the call is exactly what it was before minus 0 (since transfer failed),
        // but only if the call succeeded. The bug reverts so we never check.
        // So we assert that the call succeeded (no revert) for reference; bug reverts for non-zero receiver.
        bool ok = false;
        // Re-run with try/catch to capture revert
        address payable target = payable(address(reverter));
        try c.sendTo(target, amount) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

