        address owner = address(uint160(uint256(keccak256(abi.encodePacked("owner"))))); // Derive a deterministic owner
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.assume(receiver != owner);
        vm.assume(amount <= address(c).balance); // ensure we don't overfund contract
        // Bound amount to a reasonable range to avoid overflow / bal constraints
        amount = bound(amount, 1, 1000 ether);

        // 2. Setup: we need to call sendTo as owner. The constructor set msg.sender as owner.
        // In setUp, c = new C() makes this test contract the owner. So we prank from address(this).
        // Fund the contract with enough ether to cover the transfer.
        vm.deal(address(c), amount);

        // 3. Capture balances before call
        uint256 receiverBalBefore = receiver.balance;
        uint256 ownerBalBefore = owner.balance;
        uint256 contractBalBefore = address(c).balance;

        // 4. Call sendTo as owner
        vm.prank(owner);
        c.sendTo(receiver, amount);

        // 5. Capture balances after call
        uint256 receiverBalAfter = receiver.balance;
        uint256 ownerBalAfter = owner.balance;
        uint256 contractBalAfter = address(c).balance;

        // 6. General rule: the sum of balances of receiver and owner before and after,
        // excluding contract balance changes, must reflect that only 'amount' moved from the contract.
        // More precisely: (receiverBalAfter - receiverBalBefore) + (ownerBalAfter - ownerBalBefore) == amount
        // because the correct contract sends amount to receiver and owner should not gain.
        // The bug sends amount to owner instead, so owner gains and receiver gains nothing.
        uint256 receiverDelta = receiverBalAfter - receiverBalBefore;
        uint256 ownerDelta = ownerBalAfter - ownerBalBefore;
        assertTrue(receiverDelta + ownerDelta == amount);
    }
}
